use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

// The six legendary classes in picker order. The picker's `Boots` group sorts
// after them ([`category_rank`]) but has no Item Stats filter row.
pub const CATEGORY_ORDER: [&str; 6] =
    ["Assassin", "Fighter", "Marksman", "Mage", "Tank", "Support"];

// Every item's class, generated by build.rs from `text/item_classes.json`, the
// one place a class is written. The file also ships for `item_scroller_tfm2` to
// read.
include!(concat!(env!("OUT_DIR"), "/item_classes.rs"));

const fn str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

// A class the picker does not know would sort after Boots and match no Item
// Stats filter row, so a typo in the file stops the build instead.
const _: () = {
    let mut i = 0;
    while i < CATEGORY_OF.len() {
        let class = CATEGORY_OF[i].1;
        let mut known = str_eq(class, "Boots");
        let mut j = 0;
        while j < CATEGORY_ORDER.len() {
            known |= str_eq(class, CATEGORY_ORDER[j]);
            j += 1;
        }
        assert!(
            known,
            "text/item_classes.json names a class that is not Boots or in CATEGORY_ORDER"
        );
        i += 1;
    }
};

const RESKIN_ICON: &[(&str, &str)] = &[
    ("bloodthirster", "t4_0"),
    ("dragons_claw", "t4_3"),
    ("ludens_tempest", "t4_4"),
    ("phantom_dancer", "t4_1"),
    ("sunfire_cape", "t4_5"),
    ("thornmail", "t4_2"),
];

pub fn icon_frame(slug: &str, is_mod_item: bool) -> Option<&str> {
    if let Ok(index) = RESKIN_ICON.binary_search_by_key(&slug, |(key, _)| key) {
        return Some(RESKIN_ICON[index].1);
    }
    is_mod_item.then_some(slug)
}

pub fn category_of(slug: &str) -> Option<&'static str> {
    CATEGORY_OF
        .binary_search_by_key(&slug, |(key, _)| key)
        .ok()
        .map(|index| CATEGORY_OF[index].1)
}

// The class another enabled mod gives one of its own items, in a
// `text/item_classes.json` shaped like ours: `key` as written, else its
// `radiant_`-less slug. Only the Build Editor asks, so that mod's finals can be
// picked there; Smart Builds and the Item Stats filters keep to
// [`category_of`]. Never consulted for an item [`category_of`] knows.
pub fn other_mod_class(key: &str) -> Option<&'static str> {
    let classes = other_mod_classes();
    classes
        .get(key)
        .or_else(|| classes.get(crate::build_config::base_slug(key)))
        .copied()
}

// Every other enabled mod's `text/item_classes.json`, read once, a later mod's
// class winning as its text does ([`crate::game_text::other_mod_folders`]). A
// class that is not Boots or one of [`CATEGORY_ORDER`] is skipped, matched
// without regard to case; so is a file that is not a JSON object.
fn other_mod_classes() -> &'static HashMap<String, &'static str> {
    static CLASSES: OnceLock<HashMap<String, &'static str>> = OnceLock::new();
    CLASSES.get_or_init(|| {
        let mut classes = HashMap::new();
        let exe_dir = std::env::current_exe()
            .ok()
            .and_then(|exe| exe.parent().map(Path::to_path_buf));
        let folders = exe_dir
            .as_deref()
            .map(crate::game_text::other_mod_folders)
            .unwrap_or_default();
        for folder in folders {
            let Ok(text) = std::fs::read_to_string(folder.join("text").join("item_classes.json"))
            else {
                continue;
            };
            let Ok(serde_json::Value::Object(map)) =
                serde_json::from_str::<serde_json::Value>(text.trim_start_matches('\u{feff}'))
            else {
                continue;
            };
            for (key, class) in map {
                let known = class.as_str().and_then(|class| {
                    CATEGORY_ORDER
                        .into_iter()
                        .chain(["Boots"])
                        .find(|name| name.eq_ignore_ascii_case(class))
                });
                if let Some(class) = known {
                    classes.insert(key, class);
                }
            }
        }
        classes
    })
}

pub fn category_rank(category: &str) -> usize {
    CATEGORY_ORDER
        .iter()
        .position(|name| *name == category)
        .unwrap_or(CATEGORY_ORDER.len())
}

// The game's own thirty items as (League name, used in `config.json` and
// builds; the game's key). [`GAME_RADIANTS`] is read off it.
pub const GAME_ITEM_NAMES: [(&str, &str); 30] = [
    ("long_sword", "iron_blade"),
    ("pickaxe", "soldiers_longsword"),
    ("vampiric_scepter", "ruinous_blade"),
    ("bloodthirster", "conquerors_greatsword"),
    ("radiant_bloodthirster", "warlords_final_judgement"),
    ("dagger", "dagger"),
    ("recurve_bow", "wind_dagger"),
    ("zeal", "twin_stormblade"),
    ("phantom_dancer", "thunderclaw"),
    ("radiant_phantom_dancer", "storm_sovereign"),
    ("cloth_armor", "steel_armor"),
    ("chain_vest", "gatekeepers_armor"),
    ("bramble_vest", "black_knights_heavy_plate"),
    ("thornmail", "eternal_iron_plate"),
    ("radiant_thornmail", "impregnable_fortress"),
    ("null_magic_mantle", "mystic_cloak"),
    ("negatron_cloak", "night_hood"),
    ("spectres_cowl", "dusk_raven"),
    ("dragons_claw", "souls_edge"),
    ("radiant_dragons_claw", "veil_of_annihilation"),
    ("amplifying_tome", "arcane_crystal"),
    ("blasting_wand", "spirit_crystal"),
    ("lost_chapter", "staff_of_rapture"),
    ("ludens_tempest", "angels_fang"),
    ("radiant_ludens_tempest", "prophet_of_the_abyss"),
    ("ruby_crystal", "vital_orb"),
    ("kindlegem", "hardened_heart"),
    ("giants_belt", "ring_of_reincarnation"),
    ("sunfire_cape", "hourglass_of_eternity"),
    ("radiant_sunfire_cape", "giants_horn_shard"),
];

// The game's six radiants as (mod name, game key, game key of the legendary
// under it), derived from [`GAME_ITEM_NAMES`] at build time.
pub const GAME_RADIANTS: [(&str, &str, &str); 6] = game_radiants();

// Whether `name` is `radiant_` followed by `of`.
const fn is_radiant_of(name: &str, of: &str) -> bool {
    let (name, of, prefix) = (name.as_bytes(), of.as_bytes(), b"radiant_");
    if name.len() != prefix.len() + of.len() {
        return false;
    }
    let mut i = 0;
    while i < name.len() {
        let wanted = if i < prefix.len() {
            prefix[i]
        } else {
            of[i - prefix.len()]
        };
        if name[i] != wanted {
            return false;
        }
        i += 1;
    }
    true
}

// [`GAME_RADIANTS`], in the order of [`GAME_ITEM_NAMES`]. A table that gives
// other than six stops the build.
const fn game_radiants() -> [(&'static str, &'static str, &'static str); 6] {
    let items = GAME_ITEM_NAMES;
    let mut out = [("", "", ""); 6];
    let mut found = 0;
    let mut i = 0;
    while i < items.len() {
        let mut j = 0;
        while j < items.len() {
            if is_radiant_of(items[i].0, items[j].0) {
                assert!(found < out.len(), "GAME_ITEM_NAMES has more radiants than GAME_RADIANTS");
                out[found] = (items[i].0, items[i].1, items[j].1);
                found += 1;
            }
            j += 1;
        }
        i += 1;
    }
    assert!(found == out.len(), "GAME_ITEM_NAMES has fewer radiants than GAME_RADIANTS");
    out
}
